/**
 * Default configuration for the @mohammed_kashif/requestid middleware.
 *
 * These values are merged with user-supplied options at initialization time.
 * Every field here is intentionally explicit so the resulting config object
 * is self-documenting and easy to introspect in a debugger.
 */

export const DEFAULT_HEADER_NAME = "X-Request-ID";
export const DEFAULT_STRATEGY    = "uuid";
export const DEFAULT_PREFIX      = "";
export const MAX_INCOMING_ID_LENGTH = 128;

/** Characters allowed in an incoming request-id (allowlist approach). */
export const INCOMING_ID_PATTERN = /^[a-zA-Z0-9_\-.:]+$/;

/**
 * Full default options object.
 * @type {import('../index.js').RequestIdOptions}
 */
export const defaults = Object.freeze({
  headerName:       DEFAULT_HEADER_NAME,
  strategy:         DEFAULT_STRATEGY,
  prefix:           DEFAULT_PREFIX,
  useIncoming:      false,
  validateIncoming: true,
  exposeHeader:     true,
  generator:        undefined,
});
